vector<vector<int>> selectionSortTrace(vector<int> a) {
    vector<vector<int>> rounds;
    int n = (int)a.size();
    for (int i = 0; i < n - 1; ++i) {
        int best = i;                       // track the INDEX, not the value
        for (int j = i + 1; j < n; ++j)
            if (a[j] < a[best]) best = j;
        swap(a[i], a[best]);                // exactly one swap per round
        rounds.push_back(a);
    }
    return rounds;
}

