def selection_sort_trace(a: list[int]) -> list[list[int]]:
    a = a[:]
    rounds = []
    n = len(a)
    for i in range(n - 1):
        best = i                      # track the INDEX, not the value
        for j in range(i + 1, n):
            if a[j] < a[best]:
                best = j
        a[i], a[best] = a[best], a[i]  # exactly one swap per round
        rounds.append(a[:])
    return rounds

