vector<int> insertionSortDescending(vector<int> a) {
    for (size_t i = 1; i < a.size(); ++i) {
        int key = a[i];
        int j = (int)i - 1;
        while (j >= 0 && a[j] < key) {   // '<' instead of '>': the ONLY change
            a[j + 1] = a[j];
            --j;
        }
        a[j + 1] = key;
    }
    return a;
}

vector<int> sortEvenPositions(vector<int> a) {
