// Counts elements that sit more than one position from where sorting puts them.
int outOfPlaceCount(const vector<int>& a) {
    vector<int> sorted_ = a;
    sort(sorted_.begin(), sorted_.end());
    int count = 0;
    for (size_t i = 0; i < a.size(); ++i)
        if (a[i] != sorted_[i]) {
            // how far is this value from index i in the sorted order?
            auto it = lower_bound(sorted_.begin(), sorted_.end(), a[i]);
            if (abs((int)(it - sorted_.begin()) - (int)i) > 1) ++count;
        }
    return count;
}

bool isNearlySorted(const vector<int>& a, int k) {
    return outOfPlaceCount(a) <= k;
}

