def out_of_place_count(a: list[int]) -> int:
    """Counts elements more than one position from where sorting puts them."""
    import bisect
    s = sorted(a)
    count = 0
    for i, v in enumerate(a):
        if v != s[i]:
            pos = bisect.bisect_left(s, v)
            if abs(pos - i) > 1:
                count += 1
    return count


def is_nearly_sorted(a: list[int], k: int) -> bool:
    return out_of_place_count(a) <= k

