// Sorts by score only. Equal scores must keep their original relative order.
vector<pair<int,int>> stableInsertionByScore(vector<pair<int,int>> v) {
    for (size_t i = 1; i < v.size(); ++i) {
        auto key = v[i];
        int j = (int)i - 1;
        while (j >= 0 && v[j].first > key.first) {   // STRICT '>': equals stop the shift
            v[j + 1] = v[j];
            --j;
        }
        v[j + 1] = key;
    }
    return v;
}

pair<int,int> minMaxPairwise(const vector<int>& a) {
    int n = (int)a.size();
    int lo, hi, start;
    if (n % 2 == 0) {                       // seed with the first PAIR
        lo = min(a[0], a[1]);
        hi = max(a[0], a[1]);
        start = 2;
    } else {                                // odd: seed both with the first element
        lo = hi = a[0];
        start = 1;
    }
    for (int i = start; i + 1 < n; i += 2) {
        int small = a[i], big = a[i + 1];
        if (small > big) swap(small, big);  // 1 comparison for the pair
        lo = min(lo, small);                // loser only ever challenges min
        hi = max(hi, big);                  // winner only ever challenges max
    }
    return {lo, hi};
}

