int minDifference(vector<int> a, int m) {
    if (m == 0 || (int)a.size() < m) return 0;
    sort(a.begin(), a.end());
    int best = INT_MAX;
    for (size_t i = 0; i + m - 1 < a.size(); ++i)
        best = min(best, a[i + m - 1] - a[i]);   // window ends are the extremes
    return best;
